try{$users=lvq($db,"SELECT u.*,r.name role_name,r.slug role_slug FROM users u JOIN roles r ON r.id=u.role_id WHERE u.status='active' AND r.slug IN('administrateur','direction') LIMIT 2")->fetchAll();if(count($users)<2)throw new RuntimeException('Deux utilisateurs requis.');$a=$users[0];$v=$users[1];$mut=(int)lvq($db,"SELECT id FROM sites WHERE code='FARM-MUT'")->fetchColumn();$pig=(int)lvq($db,"SELECT id FROM livestock_species WHERE code='PORC'")->fetchColumn();$fish=(int)lvq($db,"SELECT id FROM livestock_species WHERE code='TILAPIA'")->fetchColumn();$bird=(int)lvq($db,"SELECT id FROM livestock_species WHERE code='POULET'")->fetchColumn();Auth::login($a);Auth::selectSite((string)$mut);$a=Auth::user();$m=new Livestock();$s=random_int(10000,99999);$housing=$m->createFacility(['code'=>'TST-H-'.$s,'name'=>'Test porcs','facility_type'=>'housing','area_m2'=>'','capacity_heads'=>100]);$pond=$m->createFacility(['code'=>'TST-E-'.$s,'name'=>'Étang test','facility_type'=>'pond','area_m2'=>200,'capacity_heads'=>1000]);$coop=$m->createFacility(['code'=>'TST-P-'.$s,'name'=>'Poulailler test','facility_type'=>'poultry_house','area_m2'=>'','capacity_heads'=>100]);$x['facilities']=[$housing,$pond,$coop];$pigBatch=$m->createBatch(['species_id'=>$pig,'facility_id'=>$housing,'purpose'=>'fattening','started_at'=>date('Y-m-d',strtotime('-100 days')),'initial_heads'=>10,'initial_average_weight_kg'=>20,'initial_total_weight_kg'=>''],$a);$fishBatch=$m->createBatch(['species_id'=>$fish,'facility_id'=>$pond,'purpose'=>'meat','started_at'=>date('Y-m-d',strtotime('-60 days')),'initial_heads'=>500,'initial_average_weight_kg'=>0.05,'initial_total_weight_kg'=>25],$a);$birdBatch=$m->createBatch(['species_id'=>$bird,'facility_id'=>$coop,'purpose'=>'laying','started_at'=>date('Y-m-d',strtotime('-30 days')),'initial_heads'=>50,'initial_average_weight_kg'=>1,'initial_total_weight_kg'=>''],$a);$x['batches']=[$pigBatch,$fishBatch,$birdBatch];$m->weigh(['batch_id'=>$pigBatch,'sample_heads'=>5,'total_weight_kg'=>200,'weighed_at'=>date('Y-m-d H:i:s')],$a);$metric=$m->metrics($pigBatch);lvok($metric['gmq_g_day']>190&&$metric['gmq_g_day']<210,'GMQ porcin calculé depuis deux pesées');$m->poultry(['batch_id'=>$birdBatch,'production_date'=>date('Y-m-d'),'eggs_count'=>35,'mortality_heads'=>2,'sold_heads'=>0],$a);lvok((int)lvq($db,'SELECT current_heads FROM livestock_batches WHERE id=?',[$birdBatch])->fetchColumn()===48&&(int)lvq($db,'SELECT eggs_count FROM poultry_productions WHERE batch_id=?',[$birdBatch])->fetchColumn()===35,'Ponte et mortalité avicole séparées');$catch=$m->createFishCatch(['batch_id'=>$fishBatch,'input_heads'=>100,'gross_weight_kg'=>55,'tare_weight_kg'=>5,'converted_at'=>date('Y-m-d H:i:s')],$a);$x['fish_conversion']=$catch;lvok((float)lvq($db,'SELECT yield_kg_m2 FROM fish_catches WHERE conversion_id=?',[$catch])->fetchColumn()===0.25,'Rendement piscicole calculé en kg/m²');$conversion=$m->createConversion(['batch_id'=>$pigBatch,'conversion_type'=>'slaughter','input_heads'=>4,'gross_weight_kg'=>410,'tare_weight_kg'=>10,'converted_at'=>date('Y-m-d H:i:s')],$a);$x['conversion']=$conversion;try{$m->validateConversion($conversion,$a);$blocked=false;}catch(Exception$e){$blocked=true;}lvok($blocked,'Créateur empêché de valider l’abattage');Auth::login($v);Auth::selectSite((string)$mut);$v=Auth::user();$stock=$m->validateConversion($conversion,$v);$x['stock']=$stock;lvok((int)lvq($db,'SELECT current_heads FROM livestock_batches WHERE id=?',[$pigBatch])->fetchColumn()===6&&(float)lvq($db,'SELECT quantity_kg FROM livestock_weight_stocks WHERE id=?',[$stock])->fetchColumn()===400.0,'Abattage convertit formellement 4 têtes en 400 kg');try{$m->validateConversion($conversion,$v);$double=false;}catch(Exception$e){$double=true;}lvok($double,'Double conversion refusée');Auth::login($a);Auth::selectSite((string)$mut);$a=Auth::user();$tr=$m->createTransfer(['batch_id'=>$pigBatch,'weight_stock_id'=>$stock,'source_unit'=>'kg','quantity_heads'=>'','quantity_kg'=>400,'truck_plate'=>'TST-LV-01','driver_name'=>'Test'],$a);$x['transfer']=$tr;Auth::login($v);Auth::selectSite((string)$mut);$v=Auth::user();$m->approveTransfer($tr,$v);$m->dispatchTransfer($tr,$v);lvok((int)lvq($db,"SELECT COUNT(*) FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code='BTR' AND d.entity_type='livestock_transfers' AND d.entity_id=?",[$tr])->fetchColumn()===1,'Sortie boucherie crée un BTR');lvok((int)lvq($db,'SELECT batch_id FROM livestock_transfers WHERE id=?',[$tr])->fetchColumn()===$pigBatch,'BTR conserve le lot d’élevage d’origine');lvok((float)lvq($db,'SELECT quantity_kg FROM livestock_weight_stocks WHERE id=?',[$stock])->fetchColumn()===0.0,'Sortie kg utilise uniquement le stock issu de conversion');try{$m->dispatchTransfer($tr,$v);$again=false;}catch(Exception$e){$again=true;}lvok($again,'Double sortie vers la boucherie refusée');}
catch(Exception$e){echo'ERREUR - '.$e->getMessage()."\n";$fail[]=$e->getMessage();}
finally{if(!empty($x['transfer'])){lvdocs($db,$x['transfer']);lvq($db,"DELETE FROM livestock_weight_movements WHERE reference_type='livestock_transfers' AND reference_id=?",[$x['transfer']]);lvq($db,'DELETE FROM livestock_transfers WHERE id=?',[$x['transfer']]);}if(!empty($x['stock'])){lvq($db,'DELETE FROM livestock_weight_movements WHERE stock_id=?',[$x['stock']]);lvq($db,'DELETE FROM livestock_weight_stocks WHERE id=?',[$x['stock']]);}foreach([$x['conversion']??0,$x['fish_conversion']??0]as$c)if($c){lvq($db,'DELETE FROM fish_catches WHERE conversion_id=?',[$c]);lvq($db,'DELETE FROM livestock_head_movements WHERE reference_type=\'livestock_conversions\' AND reference_id=?',[$c]);lvq($db,'DELETE FROM livestock_conversions WHERE id=?',[$c]);}foreach($x['batches']??[]as$b){lvq($db,'DELETE FROM poultry_productions WHERE batch_id=?',[$b]);lvq($db,'DELETE FROM livestock_weighings WHERE batch_id=?',[$b]);lvq($db,'DELETE FROM fish_stockings WHERE batch_id=?',[$b]);lvq($db,'DELETE FROM livestock_head_movements WHERE batch_id=?',[$b]);lvq($db,'DELETE FROM livestock_batches WHERE id=?',[$b]);}foreach($x['facilities']??[]as$f)lvq($db,'DELETE FROM livestock_facilities WHERE id=?',[$f]);lvq($db,"DELETE FROM activity_logs WHERE user_agent='LivestockTest'");}ob_end_flush();if($fail)exit(1);echo"\nÉlevages conformes.\n";
